{
  "schema_version": "1.0",
  "client_scan_id": "{{client_scan_id}}",
  "device_id": "{{device_uid}}",
  "sample": {
    "sample_id": "SAMPLE-POSTMAN-001",
    "batch_id": "{{batch_code}}",
    "lot_id": "LOT-POSTMAN-001",
    "variety": "Long-grain"
  },
  "analyzed_at": "{{$isoTimestamp}}",
  "analysis": {
    "grain_count": 2500,
    "measurements": [
      {
        "code": "broken_kernels",
        "label": "Broken kernels",
        "value": 2.5,
        "unit": "percent",
        "basis": "count_percent",
        "is_estimated": false,
        "source_path": "analysis.kernels.broken"
      },
      {
        "code": "estimated_mass_broken",
        "label": "Broken kernels (estimated mass)",
        "value": 2.1,
        "unit": "percent",
        "basis": "estimated_mass_percent",
        "is_estimated": true
      }
    ]
  },
  "rice_age": {
    "age_value_months": 12,
    "age_min_months": 10,
    "age_max_months": 14,
    "age_category": "mature",
    "proportion_percent": 85.5,
    "unit": "months",
    "method": "device-model",
    "model_version": "v1.0",
    "confidence": 88,
    "validation_status": "provisional"
  },
  "evaluation": {
    "overall": "pass",
    "ruleset_version": "postman-dev-1",
    "certification_status": "device_reported",
    "parameters": [
      {
        "code": "broken_kernels",
        "basis": "count_percent",
        "measured_value": 2.5,
        "threshold_value": 5,
        "comparison_operator": "lte",
        "source_limit_text": "development fixture only",
        "status": "pass"
      }
    ]
  },
  "attachments": [
    {
      "role": "report_pdf",
      "content_type": "application/pdf",
      "filename": "postman-report.pdf"
    },
    {
      "role": "bottom_image",
      "content_type": "image/png",
      "filename": "platen-bottom.png"
    }
  ]
}

